/* eslint-disable max-len, max-params */

'use strict';

// MODULES //

var max = require( '@stdlib/math/base/special/max' );
var min = require( '@stdlib/math/base/special/min' );
var floor = require( '@stdlib/math/base/special/floor' );
var dlarfb = require( './dlarfb.js' );
var dlarft = require( './dlarft.js' );
var dorml2 = require( './dorml2.js' );


// VARIABLES //

var NBMAX = 64;
var LDT = NBMAX + 1;
var TSIZE = LDT * NBMAX;


// FUNCTIONS //

/**
* Tests whether an operation should be applied to the left side.
*
* @private
* @param {string} side - operation side
* @returns {boolean} boolean indicating if an operation should be applied to the left side
*/
function isLeftSide( side ) {
	return side === 'left';
}


// MAIN //

/**
* Applies an orthogonal matrix `Q`, formed from Householder reflectors returned by `DGELQF`, to overwrite matrix `C` by multiplying from the left or right with `Q` or `Q^T`.
*
* ## Notes
*
* -   `Q` is a real orthogonal matrix defined as the product of k elementary reflectors, Q = H(k) . . . H(2) H(1) as returned by `DGELQF`.
*
* -   `Q` is of order `M` if SIDE = 'left' and of order `N` if SIDE = 'R'.
*
* -   `DORMQR` overwrites the general real `M` by `N` matrix `C` with,
*
*     -   `Q * C`  if SIDE = 'left' and TRANS = 'no-transpose', or
*     -   `Q^T * C`  if SIDE = 'left' and TRANS = 'transpose', or
*     -   `C * Q`  if SIDE = 'right' and TRANS = 'no-transpose', or
*     -   `C * Q^T` if SIDE = 'right' and TRANS = 'transpose'.
*
* -   `WORK` must have length, `LWORK >= max(1,N)` if SIDE = `left`, and `LWORK >= max(1,M)` if SIDE = `right`.
*
* @private
* @param {string} side - specifies the side of multiplication with `C`
* @param {string} trans - `'no-transpose'` for `Q`, `'transpose'` for `Q^T`
* @param {NonNegativeInteger} M - number of rows of `C`
* @param {NonNegativeInteger} N - number of columns of `C`
* @param {NonNegativeInteger} K - number of elementary reflectors
* @param {Float64Array} A - reflector vectors from `DGELQF`
* @param {integer} strideA1 - stride of the first dimension of A
* @param {integer} strideA2 - stride of the second dimension of A
* @param {NonNegativeInteger} offsetA - starting index for A
* @param {Float64Array} TAU - scalar factors of reflectors
* @param {integer} strideTAU - stride for TAU
* @param {NonNegativeInteger} offsetTAU - starting index for TAU
* @param {Float64Array} C - input/output matrix
* @param {integer} strideC1 - stride of the first dimension of `C`
* @param {integer} strideC2 - stride of the second dimension of `C`
* @param {NonNegativeInteger} offsetC - starting index for `C`
* @param {Float64Array} WORK - workspace array
* @param {integer} strideWORK - stride for `WORK`
* @param {NonNegativeInteger} offsetWORK - starting index for `WORK`
* @param {NonNegativeInteger} LWORK - dimension of the array `WORK`
* @returns {integer} status code (0 if successful)
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var A = new Float64Array( [ 1, 0, 0 ] );
* var TAU = new Float64Array( [ 2 ] );
* var C = new Float64Array( [ 1, 3, 5, 2, 4, 6 ] );
* var WORK = new Float64Array( 64 );
*
* var info = dormlq( 'left', 'no-transpose', 2, 3, 1, A, 2, 1, 0, TAU, 1, 0, C, 3, 1, 0, WORK, 1, 0, 64 );
* // returns 0
* // C => <Float64Array>[ -1, -3, -5, 2, 4, 6 ]
* // WORK[ 0 ] => 4256
*/
function dormlq( side, trans, M, N, K, A, strideA1, strideA2, offsetA, TAU, strideTAU, offsetTAU, C, strideC1, strideC2, offsetC, WORK, strideWORK, offsetWORK, LWORK ) {
	var isTrans;
	var isLeft;
	var ldwork;
	var lwkopt;
	var lquery;
	var transt;
	var nbmin;
	var idx0;
	var idx1;
	var idx2;
	var iwt;
	var mi;
	var nb;
	var ni;
	var nq;
	var nw;
	var ic;
	var jc;
	var ib;
	var i1;
	var i2;
	var i3;
	var i;

	isLeft = isLeftSide( side );
	isTrans = ( trans === 'transpose' );
	lquery = ( LWORK === -1 );

	// NQ is the order of Q and NW is the minimum dimension of WORK
	if ( isLeft ) {
		nq = M;
		nw = max( 1, N );
	} else {
		nq = N;
		nw = max( 1, M );
	}

	nb = min( NBMAX, 32 ); // The optimal block size derived from fortran LAPACK call `ilaenv( 1, 'DORMLQ', side // trans, m, n, k, -1 ) )`
	lwkopt = ( nw * nb ) + TSIZE;
	WORK[ offsetWORK ] = lwkopt;

	if ( lquery ) {
		return 0;
	}

	// Quick return if possible
	if ( M === 0 || N === 0 || K === 0 ) {
		WORK[ offsetWORK ] = 1;
		return 0;
	}

	nbmin = 2;
	ldwork = nw;
	if ( nb > 1 && nb < K ) {
		if ( LWORK < lwkopt ) {
			nb = floor( ( LWORK - TSIZE ) / ldwork );
			nbmin = 2; // The minimal block size derived from fortran LAPACK call `ilaenv( 2, 'DORMLQ', side // trans, m, n, k, -1 ) )`
		}
	}

	if ( nb < nbmin || nb >= K ) {
		// Use unblocked code
		dorml2( side, trans, M, N, K, A, strideA1, strideA2, offsetA, TAU, strideTAU, offsetTAU, C, strideC1, strideC2, offsetC, WORK, strideWORK, offsetWORK );
	} else {
		// Use blocked code
		iwt = nw * nb;

		if ( ( isLeft && !isTrans ) || ( !isLeft && isTrans ) ) {
			i1 = 0;
			i2 = K;
			i3 = nb;
		} else {
			i1 = floor( ( K - 1 ) / nb ) * nb;
			i2 = -1;
			i3 = -nb;
		}

		if ( isTrans ) {
			transt = 'no-transpose';
		} else {
			transt = 'transpose';
		}

		if ( isLeft ) {
			ni = N;
			jc = 0;

			idx0 = offsetA + ( i1*strideA1 ) + ( i1*strideA2 );
			idx1 = offsetTAU + ( i1*strideTAU );
			idx2 = offsetC + ( i1*strideC1 ) + ( jc*strideC2 );
			for ( i = i1; ( i3 > 0 ) ? ( i < i2 ) : ( i > i2 ); i += i3 ) {
				ib = min( nb, K - i );

				// Form the triangular factor of the block reflector H = H(i) H(i+1) ... H(i+ib-1)
				dlarft( 'forward', 'rows', nq - i, ib, A, strideA1, strideA2, idx0, TAU, strideTAU, idx1, WORK, 1, LDT, offsetWORK + ( iwt * strideWORK ) );

				// H or H**T is applied to C(i:m,1:n)
				mi = M - i;
				ic = i;

				// Apply H or H**T
				dlarfb( side, transt, 'forward', 'rows', mi, ni, ib, A, strideA1, strideA2, idx0, WORK, 1, LDT, offsetWORK + ( iwt * strideWORK ), C, strideC1, strideC2, idx2, WORK, 1, ldwork, offsetWORK );
				idx0 += i3 * ( strideA1 + strideA2 );
				idx1 += i3 * strideTAU;
				idx2 += i3 * strideC1;
			}
		} else {
			mi = M;
			ic = 0;

			idx0 = offsetA + ( i1*strideA1 ) + ( i1*strideA2 );
			idx1 = offsetTAU + ( i1*strideTAU );
			idx2 = offsetC + ( ic*strideC1 ) + ( i1*strideC2 );
			for ( i = i1; ( i3 > 0 ) ? ( i < i2 ) : ( i > i2 ); i += i3 ) {
				ib = min( nb, K - i );

				// Form the triangular factor of the block reflector H = H(i) H(i+1) ... H(i+ib-1)
				dlarft( 'forward', 'rows', nq - i, ib, A, strideA1, strideA2, idx0, TAU, strideTAU, idx1, WORK, 1, LDT, offsetWORK + ( iwt * strideWORK ) );

				// H or H**T is applied to C(1:m,i:n)
				ni = N - i;
				jc = i;

				// Apply H or H**T
				dlarfb( side, transt, 'forward', 'rows', mi, ni, ib, A, strideA1, strideA2, idx0, WORK, 1, LDT, offsetWORK + ( iwt * strideWORK ), C, strideC1, strideC2, idx2, WORK, 1, ldwork, offsetWORK );
				idx0 += i3 * ( strideA1 + strideA2 );
				idx1 += i3 * strideTAU;
				idx2 += i3 * strideC2;
			}
		}
	}

	WORK[ offsetWORK ] = lwkopt;
	return 0;
}


// EXPORTS //

module.exports = dormlq;
